#define DIST_TRASHHOLD 17.0
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    float time = (iTime+15.9) * 0.254;
    vec3 color = vec3(0.0);
    float intensity = 0.0;

    int NUM_PARTICLES = 49;

    for (int i = 0; i < NUM_PARTICLES; i++) {
        float id = float(i) / float(NUM_PARTICLES);
        float particleTime =  id * sin(float(time)/10.0)*5.0;

        float theta = fract(id + particleTime * 0.000021114169) * 6.28318;
        float phi = fract(id * 1.618 + particleTime * 0.0015149) * 3.14159;

        vec3 spherePos = vec3(
            sin(phi) * cos(theta),
            sin(phi) * sin(theta),
            cos(phi)
        );

        float angle = time * 0.8;
        mat3 rotation = mat3(
            sin(angle), 0.0, -sin(angle),
            0.0, 1.0, 0.0,
            cos(angle), 0.0, cos(angle)
        );
        spherePos = rotation * spherePos;

        vec2 screenPos = spherePos.xy / (spherePos.z + 2.3 );
        float dist = length(uv - screenPos);
        if (dist<DIST_TRASHHOLD) {
        float glow = exp(-dist * 10.4);

        intensity += glow * (abs(sin(time))+0.1);
        color += glow * vec3(
            0.4 + 0.6 * sin(id * 7.28318), 
            0.3 + 0.4 * sin(time * 2.0), 
            1.0
        );
        }
    }

    color = clamp(color, 0.0,1.0);
    float i = clamp(color.r,0.1,0.9) + clamp(color.g,0.1,0.90) + clamp(color.b,0.1,0.90);
    fragColor = vec4(color*intensity*i, i/3.0) ;
}
